/**
 * Protected acceptance suite: ops dashboard intake caps.
 *
 * Test files only — no src changes. The Builder starts from this head and
 * must not edit this file. Do not edit this file to make an implementation
 * pass; return corrections to its author.
 *
 * Contract under test (builder: implement exactly this, in the served page
 * script — and re-pin the whole-page SHA and the CSP script hash in
 * ops-dashboard.ts / ops-dashboard.test.ts, which pin the exact page bytes):
 *
 * - `isValidReport` refuses a report whose `components` array holds more than
 *   MAX_COMPONENTS entries or whose `jobs` object holds more than MAX_JOBS
 *   entries. Each collection is capped independently: either one over its cap
 *   refuses the whole report, even when the other sits exactly at its cap.
 * - MAX_COMPONENTS and MAX_JOBS are both 256: current reports carry a
 *   handful of each, so 256 is 10x+ headroom while bounding rendered rows.
 * - `render` enforces the same caps defensively: called directly with an
 *   over-cap report it throws `invalid summary report` instead of rendering
 *   unbounded rows.
 * - An over-cap report therefore surfaces exactly like any other malformed
 *   report: the poll settles (never rejects), the summary carries the page's
 *   existing failure styling (`class="bad"` plus invalid/unavailable/failed
 *   text) with neither the READY nor the NOT READY heading, the `updated`
 *   status is not stamped, and the next valid poll recovers in the same page
 *   session.
 * - Reports at or under the caps render byte-identically: exact-cap reports
 *   render every row in order, and under-cap READY / NOT READY reports render
 *   the exact pinned HTML below.
 *
 * Drives the actually served dashboard page script (fetched through the
 * Worker, executed in a Node VM) with queued summary responses for the
 * poll-level tests, and calls the page's own `isValidReport` / `render` in
 * the VM for the direct tests. Synthetic stubs only — no endpoint, database,
 * credential or deployment is contacted.
 *
 * Run: node --import ./test/cloudflare-loader.mjs --test test/ops-dashboard-intake-caps-acceptance.test.ts
 */

import { test } from "node:test";
import assert from "node:assert/strict";
import vm from "node:vm";
import worker, { type Env } from "../src/index.ts";
import {
  DASHBOARD_CLIENT_ID_HEADER,
  DASHBOARD_CLIENT_SECRET_HEADER,
  OPS_DASHBOARD_PATH,
} from "../src/ops-dashboard.ts";

/** Per-collection intake caps under test. */
const MAX_COMPONENTS = 256;
const MAX_JOBS = 256;
/** Fixed refusal `render` must throw for an over-cap report (existing message). */
const INVALID_REPORT = "invalid summary report";

const DEPLOYMENT = "synthetic-intake-caps-acceptance-deployment";
const CLIENT_ID = "synthetic-intake-caps-client-id-0123456789";
const CLIENT_SECRET = "synthetic-intake-caps-client-secret-0123456789abcdef";

function workerEnv(): Env {
  return {
    CF_VERSION_METADATA: { id: DEPLOYMENT },
    OPS_DASHBOARD_CLIENT_ID: CLIENT_ID,
    OPS_DASHBOARD_CLIENT_SECRET: CLIENT_SECRET,
    REDIRECT_MAPPINGS_JSON: "[]",
    TWO_BOT: {
      getByName: () => ({
        fetch: async () =>
          new Response("unreachable in page-script acceptance tests", { status: 500 }),
      }),
    },
  } as unknown as Env;
}

const ctx = {} as ExecutionContext;
let callerSeq = 0;

async function servedPageScript(): Promise<string> {
  const headers = new Headers({ "cf-connecting-ip": `intake-caps-caller-${++callerSeq}` });
  const res = await worker.fetch(
    new Request(`https://w.invalid${OPS_DASHBOARD_PATH}`, { headers }),
    workerEnv(),
    ctx,
  );
  assert.equal(res.status, 200, "dashboard page must be served");
  const html = await res.text();
  const match = html.match(/<script>([\s\S]*?)<\/script>/i);
  assert.ok(match, "page must contain one inline script");
  return match![1]!;
}

type QueuedResponse = {
  status: number;
  contentType: string;
  /** Value returned by `res.json()`; omit to make `res.json()` throw. */
  data?: unknown;
};

const json = (status: number, data: unknown): QueuedResponse => ({
  status,
  contentType: "application/json",
  data,
});

function componentPairs(count: number): [string, string][] {
  const out: [string, string][] = [];
  for (let i = 0; i < count; i++) out.push([`comp-${i}`, i % 2 === 0 ? "ready" : "down"]);
  return out;
}

function jobsObject(count: number): Record<string, { last_success: string; consecutive_failures: number }> {
  const out: Record<string, { last_success: string; consecutive_failures: number }> = {};
  for (let i = 0; i < count; i++) {
    out[`job-${i}`] = { last_success: "2026-10-18T00:00:00Z", consecutive_failures: i };
  }
  return out;
}

function report(components: number, jobs: number): Record<string, unknown> {
  return {
    components: componentPairs(components),
    jobs: jobsObject(jobs),
    build_revision: "r1",
    build_id: "b1",
  };
}

function runPageScript(script: string, queue: QueuedResponse[]) {
  const listeners = new Map<string, () => void>();
  const fetchCalls: { url: string; headers: Record<string, string> }[] = [];
  const elements: Record<
    string,
    {
      value?: string;
      textContent?: string;
      innerHTML?: string;
      addEventListener?: (event: string, fn: () => void) => void;
    }
  > = {
    summary: { innerHTML: "" },
    status: { textContent: "disconnected" },
    clientId: { value: "test-id" },
    clientSecret: { value: "test-secret" },
    connect: {},
    disconnect: {},
  };
  for (const id of ["connect", "disconnect"]) {
    elements[id]!.addEventListener = (event: string, fn: () => void) => {
      listeners.set(`${id}:${event}`, fn);
    };
  }
  const pending = [...queue];
  const fetchImpl = async (url: string, init?: { headers?: Record<string, string> }) => {
    fetchCalls.push({ url, headers: init?.headers ?? {} });
    const next = pending.shift();
    assert.ok(next, "page polled more times than the test queued responses");
    return {
      status: next.status,
      headers: {
        get: (name: string) =>
          name.toLowerCase() === "content-type" ? next.contentType : null,
      },
      json: async () => {
        if (!("data" in next)) throw new Error("no json body");
        return next.data;
      },
    };
  };
  const sandbox: Record<string, unknown> = {
    document: {
      getElementById: (id: string) => elements[id] ?? null,
    },
    fetch: fetchImpl,
    setInterval: () => 0,
    clearInterval: () => {},
    setTimeout: (fn: () => void, ms: number) => setTimeout(fn, ms).unref(),
    clearTimeout,
    AbortController,
    console,
  };
  vm.createContext(sandbox);
  // Expose the page's own validators alongside poll; the served-script parse
  // surface is covered by the existing dashboard suite, so appending this hook
  // cannot hide a SyntaxError in the raw script.
  vm.runInContext(`${script}\n;globalThis.__hook = { poll, isValidReport, render };`, sandbox);
  const hook = vm.runInContext("__hook", sandbox) as {
    poll: () => Promise<void>;
    isValidReport: (data: unknown) => boolean;
    render: (data: unknown, status: unknown) => string;
  };
  return { elements, listeners, hook, fetchCalls };
}

function assertExplicitFailureState(
  elements: ReturnType<typeof runPageScript>["elements"],
  label: string,
) {
  const html = elements["summary"]!.innerHTML!;
  assert.ok(!html.includes(">READY<"), `${label}: over-cap must not render READY`);
  assert.ok(!html.includes("NOT READY"), `${label}: over-cap is not a NOT READY report`);
  assert.ok(
    html.includes('class="bad"'),
    `${label}: failure state must use the page's bad styling, got: ${html.slice(0, 300)}`,
  );
  assert.ok(
    /unavailable|invalid|failed/i.test(html),
    `${label}: failure state must say the report is unavailable/invalid/failed, got: ${html.slice(0, 300)}`,
  );
  assert.ok(
    !elements["status"]!.textContent!.startsWith("updated "),
    `${label}: status must not claim a fresh update for an over-cap report, got: ${elements["status"]!.textContent}`,
  );
}

// --- Pre-render refusal: over-cap reports never reach the DOM ---

test("isValidReport refuses MAX_COMPONENTS + 1 components (jobs at cap)", async () => {
  const script = await servedPageScript();
  const { hook } = runPageScript(script, []);
  assert.equal(hook.isValidReport(report(MAX_COMPONENTS + 1, MAX_JOBS)), false);
});

test("isValidReport refuses MAX_JOBS + 1 jobs (components at cap)", async () => {
  const script = await servedPageScript();
  const { hook } = runPageScript(script, []);
  assert.equal(hook.isValidReport(report(MAX_COMPONENTS, MAX_JOBS + 1)), false);
});

test("render throws on MAX_COMPONENTS + 1 components without rendering rows", async () => {
  const script = await servedPageScript();
  const { hook } = runPageScript(script, []);
  assert.throws(() => hook.render(report(MAX_COMPONENTS + 1, 0), 200), {
    message: INVALID_REPORT,
  });
});

test("render throws on MAX_JOBS + 1 jobs without rendering rows", async () => {
  const script = await servedPageScript();
  const { hook } = runPageScript(script, []);
  assert.throws(() => hook.render(report(0, MAX_JOBS + 1), 200), {
    message: INVALID_REPORT,
  });
});

test("poll with over-cap components shows the explicit failure state, not READY", async () => {
  const script = await servedPageScript();
  const { elements, hook, fetchCalls } = runPageScript(script, [
    json(200, report(MAX_COMPONENTS + 1, 1)),
  ]);
  await assert.doesNotReject(hook.poll(), "the over-cap poll must settle, not reject");
  assertExplicitFailureState(elements, "over-cap components");
  assert.equal(fetchCalls.length, 1, "the poll fetched the summary once");
  assert.equal(fetchCalls[0]!.headers[DASHBOARD_CLIENT_ID_HEADER], "test-id");
  assert.equal(fetchCalls[0]!.headers[DASHBOARD_CLIENT_SECRET_HEADER], "test-secret");
});

test("poll with over-cap jobs shows the explicit failure state, not READY", async () => {
  const script = await servedPageScript();
  const { elements, hook } = runPageScript(script, [
    json(200, report(1, MAX_JOBS + 1)),
  ]);
  await assert.doesNotReject(hook.poll(), "the over-cap poll must settle, not reject");
  assertExplicitFailureState(elements, "over-cap jobs");
});

test("next valid poll recovers after an over-cap refusal without reconnecting", async () => {
  const script = await servedPageScript();
  const recovered = {
    components: [["gateway", "ready"]],
    jobs: {},
    build_revision: "r2",
    build_id: "b2",
  };
  const { elements, hook, fetchCalls } = runPageScript(script, [
    json(200, report(MAX_COMPONENTS + 1, 0)),
    json(200, recovered),
  ]);
  await assert.doesNotReject(hook.poll(), "over-cap poll must settle");
  assertExplicitFailureState(elements, "over-cap poll");
  // Same page session, same poll function: no Connect click, no reload.
  await assert.doesNotReject(hook.poll(), "recovery poll must settle");
  const html = elements["summary"]!.innerHTML!;
  assert.ok(html.includes(">READY<"), "recovery renders READY");
  assert.ok(html.includes("gateway"), "recovery renders the new report");
  assert.ok(html.includes("r2"), "recovery shows the new build");
  assert.ok(
    elements["status"]!.textContent!.startsWith("updated "),
    "recovery stamps the update time",
  );
  assert.equal(fetchCalls.length, 2, "both polls fetched the summary");
});

// --- Controls: at-cap and under-cap behavior stays byte-identical ---

test("control: exact-cap report validates and renders every row in order", async () => {
  const script = await servedPageScript();
  const { hook } = runPageScript(script, []);
  const data = report(MAX_COMPONENTS, MAX_JOBS);
  assert.equal(hook.isValidReport(data), true);
  const html = hook.render(data, 200);
  assert.ok(html.includes('<h2 class="ok">READY</h2>'), "status 200 renders READY");
  assert.equal(
    html.match(/<tr><td>/g)?.length ?? 0,
    MAX_COMPONENTS + MAX_JOBS,
    "every component and job row renders",
  );
  assert.ok(
    html.indexOf("<td>comp-0</td>") < html.indexOf("<td>comp-255</td>"),
    "component rows render in order",
  );
  assert.ok(
    html.indexOf("<td>job-0</td>") < html.indexOf("<td>job-255</td>"),
    "job rows render in order",
  );
  assert.ok(html.includes('<p class="muted">build r1 / b1</p>'), "build footer renders");
});

const READY_REPORT = {
  components: [["process", "ready"], ["gateway", "ready"]],
  jobs: { sweep: { last_success: "2026-10-18T00:00:00Z", consecutive_failures: 0 } },
  build_revision: "r1",
  build_id: "b1",
};

const READY_HTML =
  '<h2 class="ok">READY</h2>' +
  "<h3>Components</h3><table><tr><th>name</th><th>state</th></tr>" +
  "<tr><td>process</td><td>ready</td></tr>" +
  "<tr><td>gateway</td><td>ready</td></tr>" +
  "</table>" +
  "<h3>Jobs</h3><table><tr><th>job</th><th>last success</th><th>failures</th></tr>" +
  "<tr><td>sweep</td><td>2026-10-18T00:00:00Z</td><td>0</td></tr>" +
  "</table>" +
  '<p class="muted">build r1 / b1</p>';

test("control: under-cap READY report renders byte-identically", async () => {
  const script = await servedPageScript();
  const { hook } = runPageScript(script, []);
  assert.equal(hook.isValidReport(READY_REPORT), true);
  assert.equal(hook.render(READY_REPORT, 200), READY_HTML);
});

const NOT_READY_REPORT = {
  components: [["process", "ready"], ["gateway", "down"]],
  jobs: {},
  gateway_failure: { phase: "connect", class: "timeout" },
  build_revision: "r1",
  build_id: "b1",
};

const NOT_READY_HTML =
  '<h2 class="bad">NOT READY</h2>' +
  "<h3>Components</h3><table><tr><th>name</th><th>state</th></tr>" +
  "<tr><td>process</td><td>ready</td></tr>" +
  "<tr><td>gateway</td><td>down</td></tr>" +
  "</table>" +
  "<h3>Jobs</h3><table><tr><th>job</th><th>last success</th><th>failures</th></tr>" +
  "</table>" +
  "<p>gateway failure: connect / timeout</p>" +
  '<p class="muted">build r1 / b1</p>';

test("control: under-cap 503 report renders NOT READY byte-identically", async () => {
  const script = await servedPageScript();
  const { hook } = runPageScript(script, []);
  assert.equal(hook.isValidReport(NOT_READY_REPORT), true);
  assert.equal(hook.render(NOT_READY_REPORT, 503), NOT_READY_HTML);
});

test("control: valid poll renders READY and stamps updated", async () => {
  const script = await servedPageScript();
  const { elements, hook, fetchCalls } = runPageScript(script, [json(200, READY_REPORT)]);
  await assert.doesNotReject(hook.poll());
  assert.equal(elements["summary"]!.innerHTML, READY_HTML);
  assert.ok(
    elements["status"]!.textContent!.startsWith("updated "),
    "valid poll stamps the update time",
  );
  assert.equal(fetchCalls.length, 1, "the poll fetched the summary once");
});
